import { newSpecPage } from '@stencil/core/testing';
import { ScSubscriptionDetails } from '../sc-subscription-details';

/**
 * A pause is `cancel_at_period_end` + `restore_at` — the same shape as a cancellation
 * without `restore_at`, so these cases guard the renewal copy against telling a customer
 * their paused plan is being canceled.
 */
const renewalText = async (subscription: any) => {
  const page = await newSpecPage({
    components: [ScSubscriptionDetails],
    html: `<sc-subscription-details></sc-subscription-details>`,
  });
  page.root.subscription = subscription;
  await page.waitForChanges();
  return page.root.shadowRoot.textContent;
};

describe('sc-subscription-details', () => {
  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScSubscriptionDetails],
      html: `<sc-subscription-details></sc-subscription-details>`,
    });
    expect(page.root).toMatchSnapshot();
  });

  it('gives both dates when a pause is scheduled', async () => {
    expect(
      await renewalText({
        status: 'active',
        cancel_at_period_end: 1786000000,
        current_period_end_at: 1786000000,
        current_period_end_at_date: 'March 1, 2026',
        restore_at: 1817000000,
        restore_at_date: 'June 1, 2026',
      }),
    ).toContain('Your plan will be paused on March 1, 2026 and will resume on June 1, 2026');
  });

  it('gives the resume date once the pause has taken effect', async () => {
    expect(
      await renewalText({
        status: 'canceled',
        restore_at: 1817000000,
        restore_at_date: 'June 1, 2026',
      }),
    ).toContain('Your plan is paused and will resume on June 1, 2026');
  });

  it('still says canceled when there is no restore date', async () => {
    expect(
      await renewalText({
        status: 'active',
        cancel_at_period_end: 1786000000,
        current_period_end_at: 1786000000,
        current_period_end_at_date: 'March 1, 2026',
        restore_at: null,
      }),
    ).toContain('Your plan will be canceled on March 1, 2026');
  });
});
